            "SkipDim1",
            "OneOff",
            "NoProb",
            "NoProbOpp",
            "Dec4",
            "Dec3",
            "Dec2",
            'Svm',
            'Out0',
            'Reshape',
            'SklCol',
            'DF',
            'OneOffArray'
        ) {
            res[opt] = True;
        } else {
            raise NameError("Unable to parse option '{}'".format(opts[1:]));
        }
    }
    return res;
}

