glob ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789";

glob MAX_UNBIASED_BYTE = (256 // len(ALPHABET)) * len(ALPHABET);

def:pub nanoid(size: int = 21) -> str {

    if size < 0 {
        raise ValueError("ID size must be a non-negative safe integer");
    }
    id = "";
    while len(id) < size {
        remaining = size - len(id);
        nbytes = ((remaining * 256) + MAX_UNBIASED_BYTE - 1) // MAX_UNBIASED_BYTE;
        for byte in secrets.token_bytes(nbytes) {
            if byte >= MAX_UNBIASED_BYTE {
                continue;
            }
