def padTrimValue(value: str, decimalSeparator: str | None = None, decimalScale: int | None = None) -> str {
    if (
        decimalScale is None
        or decimalSeparator == ""
        or decimalSeparator is None
        or value == ""
    ) {
        return value;
    }

    if RegExp("\\d").search(value) is None {
        return "";
    }

    parts = value.split(decimalSeparator);
    intPart = parts[0];
    decimals = parts[1] if len(parts) > 1 else None;

    if decimalScale == 0 {
        return intPart;
    }

    newValue = decimals or "";

    while len(newValue) < decimalScale {
        newValue += "0";
    }
    if len(newValue) > decimalScale {
        newValue = newValue[0:decimalScale];
    }

    return f"{intPart}{decimalSeparator}{newValue}";
}

