glob wrapTextCache = QuickLRU(maxSize=4096);

def wrapText(text: str, maxWidth: int, wrapType: str) -> str {

    cacheKey = text + str(maxWidth) + str(wrapType);
    cachedText = wrapTextCache.get(cacheKey);
    if cachedText is not None {
        return cachedText;
    }
    wrappedText = text;
    if wrapType == "wrap" {
        wrappedText = wrapAnsi(text, maxWidth, trim=False, hard=True);
    }
    if wrapType == "hard" {
        wrappedText = wrapAnsi(text, maxWidth, trim=False, hard=True, wordWrap=False);
    }
    if wrapType.startswith("truncate") {
        position: str = "end";
        if wrapType == "truncate-middle" {
            position = "middle";
        }
        if wrapType == "truncate-start" {
            position = "start";
        }
        wrappedText = cliTruncate(text, maxWidth, position=position);
    }
    wrapTextCache.set(cacheKey, wrappedText);
    return wrappedText;
}

