def isPalindrome(word: str, left: int, right: int) -> bool {
    if left >= right {
        return True;
    }
    if word[left] != word[right] {
        return False;
    }
    return isPalindrome(word, (left + 1), (right - 1));
}

def checkPalindromes(array: list[str]) -> list[bool] {
    status: list[bool] = [];
    for word in array {
        palindromeStatus = isPalindrome(word, 0, (len(word) - 1));

        status.append(palindromeStatus);
    }
    return status;
}

