}

def:pub colorize(text: str, color: str | None, type: str) -> str {
    if color is None {
        return text;
    }
    if isNamedColor(color) {
        if type == "foreground" {
            styler = getattr(chalk, color) as Callable[[str], str];
            return styler(text);
        }
        methodName = f"bg{color[0].upper()}{color[1:]}";
