        if type == "foreground" {
            return chalk.hex(color)(text);
        }
        return chalk.bgHex(color)(text);
    }
    if color.startswith("ansi256") {
        matches = ansiRegex.match(color);
        if matches is None {
            return text;
        }

        value = int(matches.group(1));
        if type == "foreground" {
            return chalk.ansi256(value)(text);
        }
        return chalk.bgAnsi256(value)(text);
