            optionHead = classOption[0];
            options = optionHead.get("options") if isinstance(optionHead, dict) else None;
            if options is not None and isinstance(options, dict) {
                values = options.get("values");
                if values is not None and isinstance(values, dict) {
                    for valueEntry in values.items() {
                        rated = rateCandidate(valueEntry, className, matchee);
                        if rated is not None {
