    (firstRating, firstCandidate, firstClassValue) = firstSuggestion;
    secondRating = secondSuggestion[0] if isinstance(secondSuggestion, tuple) else 0.0;
    hasWinningSuggestion = (
        isinstance(secondSuggestion, tuple) and firstRating - secondRating > 0.12
    );
    if len(candidates) == 1 or hasWinningSuggestion {
