def _byte_str(num: int, unit: str = 'auto', precision: int = 2) -> str {
    abs_num = abs(num);
    if unit == 'auto' {
        if abs_num < 2.0 ** 10 {
            unit = 'KB';
        } elif abs_num < 2.0 ** 20 {
            unit = 'KB';
        } elif abs_num < 2.0 ** 30 {
