import from "@utils/string" { containsOnlyDigits }

def compute(seconds: str, paddingFlag: bool) -> str {
    if not containsOnlyDigits(seconds) {
        return "";
    }
    hours = Math.floor((Number(seconds) / 3600));
    minutes = Math.floor(((Number(seconds) % 3600) / 60));
    secs = (Number(seconds) % 60);
    if paddingFlag {
        return ":".join([str(unit).zfill(2) for unit in [hours, minutes, secs]]);
    }
    return ":".join([str(unit) for unit in [hours, minutes, secs]]);
}

def:pub convertSecondsToTime(input: str, paddingFlag: bool) -> str {
    result: list[str] = [];
    lines = input.split("\n");
    for line in lines {

        seconds = line.strip();
        time = compute(seconds, paddingFlag);
        result.append(time);
    }
    return "\n".join(result);
}

