    has terminal: Terminal postinit;
    has value: int postinit;
    has startTime: int postinit;
    has eta: ETA postinit;
    has lastDrawnString: str postinit;
    has isActive: bool postinit;
    has customParams: dict[str, object] postinit;
    has timer: Timer | None = None;

    def postinit {
        self.terminal = Terminal();
        self.value = self.initValue;
        self.startTime = int(time.time() * 1000);
        totalVal = float(self.total) if self.total is not None else float("inf");
        self.eta = ETA(initValue=self.initValue, total=totalVal, bufferLength=self.bufferLength);
        self.lastDrawnString = "";
        self.isActive = True;
        self.customParams = {};
        delay = 0.1 if self.terminal.isTTY else 1.0;
        self.timer = Timer(delay, lambda { self.render(); });
        self.timer.start();
    }

    def render {
        if self.timer is not None {
            self.timer.cancel();
        }
        if not self.isActive {
            calc = self.eta.calculate();
            ratePerSecond = calc["ratePerSecond"] as float;
            totalDisplay = self.total if self.total is not None else 0;
            finishedText = f"Process finished in {(int(time.time() * 1000) - self.startTime) / 1000.0}s - Processed {self.value} of {totalDisplay} with a rate of {ratePerSecond} per second.";
            self.terminal.resetCursor();
            self.terminal.clearRight();
            self.terminal.write(finishedText);
            self.terminal.newline();
            return;
        }
        totalVal = float(self.total) if self.total is not None else float("inf");
        progress = min(max(self.value / totalVal, 0.0), 1.0);
        calc = self.eta.calculate();
        params: BarParams = {
            "progress": progress,
            "eta": calc["eta"],
            "rate": calc["ratePerSecond"],
            "startTime": self.startTime,
            "total": int(totalVal) if self.total is not None else 0,
            "value": self.value,
            "maxWidth": self.terminal.getWidth(),
        };
        rendered = defaultFormatter(self.text, params, self.customParams);
        self.terminal.resetCursor();
        self.terminal.write(rendered);
        if self.lastDrawnString != rendered and not self.terminal.isTTY {
            self.terminal.newline();
        }
        self.terminal.clearRight();
        self.lastDrawnString = rendered;
        delay = 0.1 if self.terminal.isTTY else 1.0;
        self.timer = Timer(delay, lambda { self.render(); });
        self.timer.start();
    }

    def stop {
        self.isActive = False;
    }

    def update(value: int, custom: dict[str, object] | None = None) {
        self.value = value;
        self.customParams = custom if custom is not None else {};

    self.eta.update(value);
    if self.autoStop and self.total is not None and self.value >= self.total {
        self.stop();
    }
}

