def:pub useRaf(ms: float = 1000000000000, delay: float = 0) -> float {
    elapsedPair = useState(0.0);
    elapsed: float = elapsedPair[0] as float;
    setElapsed = elapsedPair[1];

    useLayoutEffect(lambda {
        raf: float = 0.0;
        timerStop: float = 0.0;
        start = 0.0;

        def onFrame() {
            time = min(1.0, (Date.now() - start) / ms);
            setElapsed(time);
            loop();
        }

        def loop() {
            raf = requestAnimationFrame(onFrame) as float;
        }

        def onStart() {
            timerStop = setTimeout(lambda {
                cancelAnimationFrame(raf);
                setElapsed(1.0);
            }, ms) as float;

    start = Date.now();
    loop();
}

