        value={str(dropdownProps.value)}
    >
        <SelectTrigger className="first:grow">
            <SelectValue>{selectedLabel}</SelectValue>
        </SelectTrigger>
        <SelectContent align="start">
            {if options {
                for option in options {
                    <SelectItem disabled={option.disabled} key={str(option.value)} value={str(option.value)}>
                        {option.label}
                    </SelectItem>
                }
            }}
        </SelectContent>
    </Select>
}

