def:pub zIndex(nodes: list[ReactTestRendererNode | str]) -> list[dict[str, object] | str] {
    staged: list[dict[str, object] | str] = [];
    for (index, node) in enumerate(nodes) {
        if isinstance(node, str) {
            staged.append(node);
        } else {

            staged.append({"props": node.props, "oIndex": index});
        }
    }
    return sorted(staged, key=z_index_key);
}

