import from "react" { useCallback, useRef }

glob:pub ACTIONS: dict[str, str] = {"MARK": "mark", "MOVE_PAGE": "move-page", "ELEMENT": "element", "PAGE_SOURCE": "page-source"};

glob UNDO_CAP: int = 30;

def:pub useUndoStack() -> dict[str, object] {
    stackRef = useRef([]);
    cursorRef = useRef(0);
    push = useCallback(
        lambda (undo_entry: dict[str, object]) -> None {
            stack = stackRef.current[0:cursorRef.current];
            stack.append(undo_entry);
            if len(stack) > UNDO_CAP {
                stack = stack[1:];
            }
            stackRef.current = stack;
            cursorRef.current = len(stack);
        },
        []
    );
    undo = useCallback(
        lambda () -> dict[str, object] | None {
            if cursorRef.current == 0 {
                return None;
            }
            cursorRef.current -= 1;
            return stackRef.current[cursorRef.current] as dict[str, object];

        },
        []
    );
    redo = useCallback(
        lambda () -> dict[str, object] | None {
            stack = stackRef.current;
            if cursorRef.current >= len(stack) {
                return None;
            }
            item = stack[cursorRef.current];
            cursorRef.current += 1;
            return item as dict[str, object];
        },
        []
    );
    return {"push": push, "undo": undo, "redo": redo};
}

