def splitPgpassLine(a: str) -> list[str] {
    b: list[str] = [];
    escape = False;
    d = '';
    for c in a {
        if not escape and c == '\\' {
            escape = True;
        } elif not escape and c == ':' {
            b.append(d);
            d = '';
        } else {
            d += c;

            escape = False;
        }
    }
    if escape {
        d += '\\';
    }
    b.append(d);
    return b;
}

