def js_typeof(value: object) -> str {
    if value is None {
        return "object";
    }
    if isinstance(value, bool) {
        return "boolean";
    }
    if isinstance(value, int) or isinstance(value, float) {
        return "number";
    }
    if isinstance(value, str) {
        return "string";
    }
    if callable(value) {
        return "function";
    }
