import re;
import from math { log10, isfinite }
import from "./personIntent" { parsePersonIntent, resolveRoleMatch }
import from "./suggestInteraction" { inferInteractionIntent }

def levenshteinDistance(a: str, b: str) -> int {
    if a == b {
        return 0;
    }
    if not len(a) {
        return len(b);
    }
    if not len(b) {
        return len(a);
    }
    matrix: list[list[int]] = [[0 for _ in range(len(b) + 1)] for _ in range(len(a) + 1)];
    for i in range(len(a) + 1) {
        matrix[i][0] = i;
    }
    for j in range(len(b) + 1) {
        matrix[0][j] = j;
    }
    for i in range(1, len(a) + 1) {
        for j in range(1, len(b) + 1) {
            substitution_cost = 0 if a[i - 1] == b[j - 1] else 1;
            matrix[i][j] = min(
                matrix[i - 1][j] + 1,
                matrix[i][j - 1] + 1,
                matrix[i - 1][j - 1] + substitution_cost
            );
        }
    }
    return matrix[len(a)][len(b)];
}

def normalizeText(input: str) -> str {
    cleaned = re.sub(r"[^a-z0-9\s]", " ", input.lower());
    return re.sub(r"\s+", " ", cleaned).strip();
}

def extractYear(input: str) -> str | None {
    m = re.search(r"\b(19|20)\d{2}\b", input);
    return m.group(0) if m is not None else None;
}

def getFuzzySimilarity(query: str, title: str) -> float {
    normalized_query = normalizeText(query);
    normalized_title = normalizeText(title);
    if not normalized_query or not normalized_title {
        return 0.0;
    }
    distance = levenshteinDistance(normalized_query, normalized_title);
    max_len = max(len(normalized_query), len(normalized_title));
    edit_similarity = max(0.0, 1.0 - (distance / max_len)) if max_len > 0 else 0.0;
    query_tokens = [token for token in normalized_query.split(" ") if token];
    title_tokens = [token for token in normalized_title.split(" ") if token];
    title_token_set = set(title_tokens);
    token_hits = len([token for token in query_tokens if token in title_token_set]);
    token_similarity = (token_hits / len(query_tokens)) if query_tokens else 0.0;
    return round((edit_similarity * 0.6) + (token_similarity * 0.4), 3);
}

def getTitleMatchScore(query: str, title: str) -> float {
    normalized_query = normalizeText(query);
    normalized_title = normalizeText(title);
    if not normalized_query or not normalized_title {
        return 0.0;
    }
    if normalized_title == normalized_query {
        return 120.0;
    }
    if normalized_title.startswith(normalized_query) {
        return 80.0;
    }
    if normalized_query in normalized_title {
        return 45.0;
    }
    query_tokens = [token for token in normalized_query.split(" ") if token];
    title_tokens = [token for token in normalized_title.split(" ") if token];
    token_matches = 0;
    for token in query_tokens {
        if len(token) < 2 {
            continue;
        }
        for title_token in title_tokens {
            if title_token.startswith(token) or token in title_token {
                token_matches += 1;
                break;
            }
        }
    }
    if token_matches == 0 {
        return 0.0;
    }
    fuzzy_similarity = getFuzzySimilarity(normalized_query, normalized_title);
    return 18.0 + (token_matches * 10.0) + (fuzzy_similarity * 26.0);
}

def getPopularityBoost(popularity: float | None = None) -> float {
    if popularity is None or popularity <= 0 {
        return 0.0;
    }
    return min(12.0, log10(popularity + 1.0) * 4.0);
}

def getRoleMatchBoost(requestedRole: str, knownForDepartment: str | None) -> float {
    if requestedRole == "any" {
        return 0.0;
    }
    role_match = resolveRoleMatch(requestedRole, knownForDepartment);
    if role_match == "match" {
        return 30.0 if requestedRole == "director" else 26.0;
    }
    if role_match == "mismatch" {
        return -10.0;
    }
    return 0.0;
}

def getPersonFocusBoost(isPersonFocused: bool, entity_type: str) -> float {
    if not isPersonFocused {
        return 0.0;
    }
    return 22.0 if entity_type == "person" else -6.0;
}

def getYearBoost(queryYear: str | None, candidateYear: str | None) -> float {
    if not queryYear or not candidateYear {
        return 0.0;
    }
    if queryYear == candidateYear {
        return 12.0;
    }
    try {
        query_year_num = float(queryYear);
        candidate_year_num = float(candidateYear);
    } except ValueError {
        return 0.0;
    }

    if not isfinite(query_year_num) or not isfinite(candidate_year_num) {
        return 0.0;
    }
    year_distance = abs(query_year_num - candidate_year_num);
    if year_distance == 1.0 {
        return 6.0;
    }
    if year_distance == 2.0 {
        return 3.0;
    }
    return 0.0;
}

