def merge_and_count_split_inv(B: list[int], C: list[int]) -> tuple[list[int], int] {

    merged = [];
    inv_counter = 0;
    item_b = None;
    item_c = None;
    while B or C or item_b or item_c {
        if not item_b and B {
            item_b = B.pop(0);
        }
        if not item_c and C {
            item_c = C.pop(0);
