                "speed": getattr(coords, "speed"),
                "timestamp": getattr(event, "timestamp"),
            });
        }
    };

    onEventError = lambda (error: object) -> None {
        if mounted {
            setState(lambda (oldState: dict[str, object]) -> dict[str, object] {
                return {**oldState, "loading": False, "error": error};
            });
        }
    };

