obj Zip {
    has zip: object;

    def init() {
        self.zip = new(JSZip);
    }

    def addFile(file: EmptyFileInterface | FilerInterface) -> Zip {
        relPath = file.path[1:];
        if isinstance(file, FilerInterface) {
            self.zip.file(relPath, file.value);  # jac:ignore[E1030]
        } else {
            self.zip.file(relPath, "");  # jac:ignore[E1030]
        }
        return self;
    }

    def addFolder(path: str) -> Zip {
        self.zip.folder(path);  # jac:ignore[E1030]
        return self;
    }

    def addDirectory(directory: DirectoryInterface | None) -> Zip {
        if not directory {
            return self;
        }
        self.zip.folder(directory.path[1:]);  # jac:ignore[E1030]
        stack = list(directory.children);
        while stack {

        cur = stack[0];
        stack = stack[1:];
        if isFiler(cur) {
            self.addFile(cur as FilerInterface);
        } elif isDirectory(cur) {
            dirNode = cur as DirectoryInterface;
            self.addFolder(dirNode.path[1:]);
            stack = stack + dirNode.children;
        }
    }
    return self;
}

