        case "HANDLE_REDIRECT_COMPLETE" | "GET_ACCESS_TOKEN_COMPLETE" | "SYNC_USER":
            user = action["user"] as User | None;
            if state.user == user {
                return state;
            }
            return AuthState(
                isLoading=state.isLoading,
                isAuthenticated=user is not None,
                user=user,
                error=state.error,
            );

        case "LOGOUT":
            return AuthState(
                isLoading=state.isLoading,
                isAuthenticated=False,
                user=None,
                error=state.error,
            );
        case "ERROR":
            err = action["error"] as Exception;
            return AuthState(
                isLoading=False,
