def:pub byteOf(ch: str) -> int {
    return ord(ch[0]);
}

glob:pub BACKSLASH: int = byteOf("\\");
glob:pub LINE_FEED: int = byteOf("\n");
glob:pub CARRIAGE_RETURN: int = byteOf("\r");
glob:pub LEFT_PAREN: int = byteOf("(");
glob:pub RIGHT_PAREN: int = byteOf(")");
glob:pub LESS_THAN: int = byteOf("<");
glob:pub GREATER_THAN: int = byteOf(">");
glob:pub LEFT_BRACKET: int = byteOf("[");
glob:pub RIGHT_BRACKET: int = byteOf("]");
glob:pub LEFT_BRACE: int = byteOf("{");
glob:pub RIGHT_BRACE: int = byteOf("}");
glob:pub SLASH: int = byteOf("/");
glob:pub PERCENT: int = byteOf("%");
glob:pub HASH: int = byteOf("#");

glob WHITESPACE: set[int] = {
    0,
    byteOf("\t"),
    byteOf("\n"),
    byteOf("\f"),
    byteOf("\r"),
    byteOf(" ")
};

glob DELIMITERS: set[int] = {byteOf(ch) for ch in "()<>[]{}/%"};

def:pub isWhitespace(b: int) -> bool {
    return b in WHITESPACE;
}

def:pub isDelimiter(b: int) -> bool {
    return b in DELIMITERS;
}

def:pub isRegular(b: int) -> bool {
    return not isWhitespace(b) and not isDelimiter(b);
}

def:pub isNumberChar(b: int) -> bool {
    return (
        (b >= byteOf("0") and b <= byteOf("9"))
        or b == byteOf("+")
        or b == byteOf("-")
        or b == byteOf(".")
    );
}

def:pub isOctalDigit(b: int | None) -> bool {
    return b is not None and b >= byteOf("0") and b <= byteOf("7");
}

def:pub hexDigitValue(b: int | None) -> int {

    if b is None {
        return -1;
    }
    if b >= byteOf("0") and b <= byteOf("9") {
        return b - byteOf("0");
    }
    if b >= byteOf("A") and b <= byteOf("F") {
        return b - byteOf("A") + 10;
    }
    if b >= byteOf("a") and b <= byteOf("f") {
        return b - byteOf("a") + 10;
    }
    return -1;
}

