def pretty_size(size_in_bytes: int = 0, measure: str | None = None) -> str {
    size_in_bytes = size_in_bytes or 0;
    pretty_size_map = {
        "B": size_in_bytes,
        "KB": round(size_in_bytes / 1000.0, 0),
        "KiB": round(size_in_bytes / 1024.0, 0),
