obj AuthState {
    has user: object | None = None;
    has isLoading: bool = True;
    has isAuthenticated: bool = False;
    has error: ErrorContext | None = None;
    has activeNavigator: str | None = None;
}

def _is_authenticated(user: object | None) -> bool {
    if user is None {
        return False;
    }
    expired = getattr(user, "expired", False);
    return not bool(expired);
}

def reducer(state: AuthState, action: dict[str, object]) -> AuthState {
    action_type = action["type"] as str;
    match action_type {
        case "INITIALISED" | "USER_LOADED":
            user = action["user"];
            return AuthState(
                user=user,
                isLoading=False,
                isAuthenticated=_is_authenticated(user as object | None),
                error=None,
                activeNavigator=state.activeNavigator,
            );
        case "USER_SIGNED_OUT" | "USER_UNLOADED":
            return AuthState(
                user=None,
                isLoading=state.isLoading,
                isAuthenticated=False,
                error=state.error,
                activeNavigator=state.activeNavigator,
            );
        case "NAVIGATOR_INIT":
            return AuthState(
                user=state.user,
                isLoading=True,
                isAuthenticated=state.isAuthenticated,
                error=state.error,
                activeNavigator=action["method"] as str,
            );

        case "NAVIGATOR_CLOSE":
            return AuthState(
                user=state.user,
                isLoading=False,
                isAuthenticated=state.isAuthenticated,
                error=state.error,
                activeNavigator=None,
            );
        case "ERROR":
            err = action["error"] as ErrorContext;
            return AuthState(
                user=state.user,
                isLoading=False,
                isAuthenticated=state.isAuthenticated,
                error=err,
                activeNavigator=state.activeNavigator,
            );
        case _:
            inner = TypeError(f"unknown type {action_type}");
            err = ErrorContext(
                name="TypeError",
                message=str(inner),
                innerError=inner,
                stack=None,
                source="unknown",
            );
            return AuthState(
                user=state.user,
                isLoading=False,
                isAuthenticated=state.isAuthenticated,
                error=err,
                activeNavigator=state.activeNavigator,
            );
    }
}

