def sorted_list_difference(expected: list[int], actual: list[int]) -> tuple[list[int], list[int]] {
    i = j = 0;
    missing = [];
    unexpected = [];
    while True {
        try {
            e = expected[i];
            a = actual[j];
            if e < a {
                missing.append(e);
                i += 1;
                while expected[i] == e {
                    i += 1;
                }
            } elif e > a {
                unexpected.append(a);
                j += 1;
                while actual[j] == a {
                    j += 1;

                }
            } else {
                i += 1;
                try {
                    while expected[i] == e {
                        i += 1;
                    }
                } finally {
                    j += 1;
                    while actual[j] == a {
                        j += 1;
                    }
                }
            }
        } except IndexError {
            missing.extend(expected[i:]);
            unexpected.extend(actual[j:]);
            break;
        }
    }
    return (missing, unexpected);
}

