import re;

def tokenize(text: str) -> list[str] {
    tokens: list[str] = [];

    pattern = re.compile(r"[\u4e00-\u9fff\u3400-\u4dbf\uff00-\uffef\u3000-\u303f]|[a-zA-Z0-9']+|[^a-zA-Z0-9'\u4e00-\u9fff\u3400-\u4dbf\uff00-\uffef\u3000-\u303f]+");
