def:pub splitProps(props: dict[str, object], keys: list[str]) -> SplitProps {

    matchedProps: dict[str, object] = {};
    remainingProps: dict[str, object] = {};
    propKeys = list(props.keys());
    for propKey in propKeys {
        propValue = props[propKey];
        if propKey in keys {
            matchedProps[propKey] = propValue;
        } else {
            remainingProps[propKey] = propValue;
        }
    }
    return SplitProps(matchedProps=matchedProps, remainingProps=remainingProps);
}

