def:pub hashCode(name: str) -> int {
    hash_val: int = 0;
    for i in range(len(name)) {
        character = ord(name[i]);
        hash_val = ((hash_val << 5) - hash_val) + character;
        hash_val = hash_val & hash_val;
    }
    return abs(hash_val);
}

