def _tokenize_string(formula: str) -> list[str] {
    assert isinstance(formula, str);
    token_list: list[str] = [];
    accumulated = "";
    for char in formula {
        if char in ["(", ")", "+", "^", " ", "[", "]", "=", "~"] {
            if accumulated != "" {
                token_list.append(accumulated);
            }
            token_list.append(char);
            accumulated = "";
        } elif char == "*" {
            if accumulated == "*" {
                token_list.append("^");
                accumulated = "";
            } elif accumulated != "" {
                token_list.append(accumulated);
                accumulated = "*";
            } else {
                accumulated = "*";

            }
        } else {
            if accumulated == "*" {
                token_list.append(accumulated);
                accumulated = "";
            }
            accumulated += char;
        }
    }
    if accumulated != "" {
        token_list.append(accumulated);
    }
    outlist: list[str] = [];
    for item in token_list {
        if item not in [" ", "[", "]"] {
            outlist.append(item);
        } elif item == "[" {
            outlist.append(outlist.pop() + item);
        } elif item == "]" {
            if len(outlist) < 2 {
                raise SyntaxError("error in using square brackets in formula input");
            }
            outlist.append(outlist.pop(-2) + outlist.pop() + item);
