import from time { time }
import from .decode { decodeJwt }

obj JwtPayload {
    has exp: int | None = None;
}

def:pub isTokenExpired(
    token: str,
    bufferSeconds: int = 0,
    clockSkewSeconds: int = 0,
) -> bool {
    payload = decodeJwt(token) as JwtPayload;
    if payload.exp is None {
        return False;
    }
    now = time();
    return payload.exp - bufferSeconds <= now + clockSkewSeconds;
}

def:pub getTimeUntilExpiry(token: str, clockSkewSeconds: int = 0) -> float {
    payload = decodeJwt(token) as JwtPayload;
    if payload.exp is None {
        return float("inf");

    }
    now = time();
    return float(payload.exp) - now - float(clockSkewSeconds);
}

