def chunkFiller(array: list[list[str]], chunkNumber: int, padNonFullChunk: bool, paddingChar: str = "") -> list[list[str]] {

    if padNonFullChunk and len(array) > 0 {
        lastSubArray: list[str] = array[(len(array) - 1)];
