def:pub useEffect(callback: Callable[[list[object]], None], deps: list[object]) -> None {

    prevRef = useRef(deps);
    reactUseEffect(lambda {
        changed = len(deps) != len(prevRef.current);
        if not changed {
            for (i, dep) in enumerate(deps) {
                if dep != prevRef.current[i] {
                    changed = True;
                    break;
                }
            }
        }
        if changed {
            callback(prevRef.current);
        }
        prevRef.current = deps;
    });
}

