def isTypedCharGood(event: KeyboardEvent) -> bool {
    if event.metaKey or event.ctrlKey or event.altKey {
        return False;
    }
    key = event.key;
    if len(key) != 1 {
        return False;
    }
    ch = key[0];
    if ch.isdigit() {
        return True;
    }
    if (ch >= "A") and (ch <= "Z") {
        return True;
    }
    return False;
}

