glob measureTextCache: dict[str, TextDimensions] = {};

def:pub measureText(text: str) -> TextDimensions {

    if len(text) == 0 {
        return {"width": 0, "height": 0};
    }
    cachedDimensions = measureTextCache.get(text);
    if cachedDimensions is not None {
        return cachedDimensions;
    }
    lines = text.split("\n");
    width = 0;
    for line in lines {
        lineWidth = len(line);
        if lineWidth > width {
            width = lineWidth;
        }
    }
    height = len(lines);
    dimensions = {"width": width, "height": height};
    measureTextCache[text] = dimensions;
    return dimensions;
}

